# Build the correct function f carefully: paint rays until hitting a cell that is 8-adjacent to a foreign object; those adjacent cells stay bg. Then also prune painted cells that are already 8-adjacent to foreign objects? Try variant: stop ray when next cell is 8-adjacent to non-bg non-same-color cell. Test all demos.
def components(A,bgv):
    H,W=A.shape; seen=np.zeros_like(A,bool); out=[]
    for y in range(H):
        for x in range(W):
            if A[y,x]!=bgv and not seen[y,x]:
                col=int(A[y,x]); st=[(y,x)]; comp=set()
                while st:
                    yy,xx=st.pop()
                    if (yy,xx) in comp: continue
                    comp.add((yy,xx)); seen[yy,xx]=True
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=yy+dy,xx+dx
                        if 0<=ny<H and 0<=nx<W and A[ny,nx]==col: st.append((ny,nx))
                out.append((col,frozenset(comp)))
    return out
def is_foreign_adj(p,S,self_col,A):
    for q in S:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                rr,cc=q[0]+dr,q[1]+dc
                if (rr,cc)==p: continue
                if A[rr,cc]!=A[p] and A[rr,cc]!=9:
                    return True
    return False
def f(A):
    A=np.array(A); bgv=Counter(A.flatten()).most_common(1)[0][0]; H,W=A.shape
